const crypto = require('crypto');
const input = $json.body ?? $json;
const allowed = ['order.created','payment.simulated','order.status_changed','stock.changed','support.requested','return.requested','incident.created'];
const errors = [];
for (const key of ['event_id','event_type','occurred_at','source','idempotency_key','payload']) { if (input[key] === undefined || input[key] === null || input[key] === '') errors.push(`Falta ${key}`); }
if (input.event_type && !allowed.includes(input.event_type)) errors.push('event_type no permitido');
if (input.occurred_at && Number.isNaN(Date.parse(input.occurred_at))) errors.push('occurred_at no es ISO-8601');
if (typeof input.payload !== 'object' || Array.isArray(input.payload)) errors.push('payload debe ser objeto');
if (errors.length) return [{ json: { valid: false, errors, trace_id: input.event_id ?? 'unknown' } }];
const event = { event_id: String(input.event_id), event_type: String(input.event_type), occurred_at: new Date(input.occurred_at).toISOString(), source: String(input.source), idempotency_key: String(input.idempotency_key), payload: input.payload };
const raw_body = JSON.stringify(event);
const secret = $env.INTEGRATION_SHARED_SECRET;
if (!secret) return [{ json: { valid: false, errors: ['INTEGRATION_SHARED_SECRET no configurado'], trace_id: event.event_id } }];
const signature = crypto.createHmac('sha256', secret).update(raw_body).digest('hex');
return [{ json: { valid: true, event, raw_body, signature: `sha256=${signature}`, idempotency_key: event.idempotency_key, trace_id: event.event_id, is_post_sale: ['support.requested','return.requested','incident.created'].includes(event.event_type) } }];

const response = $json;
const ok = response.ok === true || response.status === 'SUCCESS';
return [{ json: { ok, trace_id: response.trace_id ?? $('Validar normalizar y firmar').item.json.trace_id, integration_id: response.integration_id ?? null, entity_type: response.entity_type ?? null, entity_id: response.entity_id ?? null, duplicate: response.duplicate ?? false, follow_up: $('Validar normalizar y firmar').item.json.is_post_sale ? 'Caso postventa disponible para análisis supervisado' : 'Sin seguimiento adicional', processed_at: new Date().toISOString() } }];
